"use client";

import { useReducedMotion } from "motion/react";
import { useId, useMemo, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { formatMoney } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import {
  ACCOUNTS,
  GROUPINGS,
  type GroupingId,
  HEALTH,
  HEALTH_ORDER,
  layoutGalaxy,
} from "./customer-galaxy/data";
import { GalaxyCanvas } from "./customer-galaxy/galaxy-canvas";
import { GalaxyPanel } from "./customer-galaxy/galaxy-panel";
import { useInView } from "./lib/use-in-view";
import { useTokenColors } from "./lib/use-token-colors";

/**
 * Every Fernhill account as one dot in a drifting cloud, sized by monthly
 * revenue and coloured by health. Changing the grouping spirals the dots
 * into clusters. A person flies between clusters, steps through accounts,
 * and reads the same split in the panel's ranked rows.
 */
export function CustomerGalaxy({ className }: { className?: string }) {
  const titleId = useId();
  const box = useRef<HTMLDivElement>(null);
  const inView = useInView(box);
  const colors = useTokenColors(box);
  const reduceMotion = useReducedMotion() ?? false;
  const [groupingId, setGroupingId] = useState<GroupingId>("plan");
  const [focus, setFocus] = useState<number | null>(null);
  const [selected, setSelected] = useState<number | null>(null);

  const grouping =
    GROUPINGS.find((item) => item.id === groupingId) ?? GROUPINGS[0]!;
  const { clusters, targets } = useMemo(
    () => layoutGalaxy(grouping),
    [grouping],
  );
  const account = selected === null ? null : ACCOUNTS[selected];
  const cluster = focus === null ? null : clusters[focus];

  const readout = account
    ? `${account.name}: ${formatMoney(account.revenue)} a month, ${HEALTH[account.health].label.toLowerCase()}, ${account.plan} plan.`
    : cluster
      ? `${cluster.name}: ${cluster.members.length} accounts, ${formatMoney(cluster.revenue)} a month. Up and down step through its largest accounts.`
      : `${ACCOUNTS.length} accounts in ${clusters.length === 1 ? "one cloud" : `${clusters.length} clusters by ${grouping.label.toLowerCase()}`}.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 px-5 pt-5">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Every account at a glance
          </h2>
          <p className="text-sm text-muted-foreground">
            Each dot is a clinic, sized by what it pays each month.
          </p>
        </div>
        <div className="max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none">
          <SegmentedControl
            aria-label="Group accounts by"
            options={GROUPINGS.map((item) => ({
              value: item.id,
              label: item.label,
            }))}
            value={groupingId}
            onValueChange={(next) => {
              setGroupingId(next);
              setFocus(null);
              setSelected(null);
            }}
          />
        </div>
      </header>

      <div
        className="flex flex-wrap items-center gap-x-4 gap-y-2 px-5 pt-3 text-xs text-muted-foreground"
        aria-hidden="true"
      >
        {HEALTH_ORDER.map((health) => (
          <span key={health} className="flex items-center gap-1.5">
            <span className={`size-2.5 rounded-full ${HEALTH[health].fill}`} />
            {HEALTH[health].label}
          </span>
        ))}
        <span className="flex items-center gap-1.5">
          <span className="size-1.5 rounded-full border border-muted-foreground" />
          <span className="size-2.5 rounded-full border border-muted-foreground" />
          <span className="size-4 rounded-full border border-muted-foreground" />
          Size shows monthly revenue
        </span>
      </div>

      <div
        ref={box}
        className="grid gap-5 px-5 py-4 @3xl:grid-cols-[1fr_16rem]"
      >
        <div className="flex min-w-0 flex-col gap-2">
          <GalaxyCanvas
            clusters={clusters}
            targets={targets}
            focus={focus}
            onFocus={(next) => {
              setFocus(next);
              setSelected(null);
            }}
            selected={selected}
            onSelect={setSelected}
            colors={colors}
            reduceMotion={reduceMotion}
            active={inView}
            label="Account map. Left and right fly between clusters, up and down step through accounts, plus and minus zoom, Escape goes back."
          />
          <p role="status" className="text-sm text-muted-foreground">
            {readout}
          </p>
        </div>
        <GalaxyPanel
          clusters={clusters}
          focus={focus}
          onFocus={(next) => {
            setFocus(next);
            setSelected(null);
          }}
        />
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { seededRandom } from "../../lib/plot";

/** The ways a person can group the accounts. */
export type GroupingId = "all" | "plan" | "region" | "health" | "industry";

/** How an account is doing, which sets its colour. */
export type Health = "healthy" | "steady" | "risk" | "leaving";

/** One clinic that pays Fernhill every month. */
export interface Account {
  id: number;
  name: string;
  plan: string;
  region: string;
  industry: string;
  health: Health;
  /** Monthly revenue in pounds. */
  revenue: number;
}

/** A grouping, its tab label, and the order its groups appear in. */
export interface Grouping {
  id: GroupingId;
  label: string;
  groups: string[];
  of: (account: Account) => string;
}

/** The words and colour for each state of health. */
export const HEALTH = {
  healthy: { label: "Healthy", hue: 1, fill: "bg-chart-2" },
  steady: { label: "Steady", hue: 0, fill: "bg-chart-1" },
  risk: { label: "At risk", hue: 2, fill: "bg-chart-3" },
  leaving: { label: "Leaving", hue: 4, fill: "bg-chart-5" },
} satisfies Record<Health, { label: string; hue: number; fill: string }>;

/** The order the states of health are listed and drawn in. */
export const HEALTH_ORDER: Health[] = ["healthy", "steady", "risk", "leaving"];

const PLANS = ["Solo", "Team", "Group"];
const REGIONS = ["Scotland", "North", "Midlands", "Wales", "South"];
// Each industry and the word that ends a clinic's name in it.
const INDUSTRIES = [
  { name: "Physio", ending: "Physio" },
  { name: "Dental", ending: "Dental" },
  { name: "Family practice", ending: "Surgery" },
  { name: "Therapy", ending: "Therapy" },
  { name: "Vets", ending: "Vets" },
];
const FIRST = [
  "Alder",
  "Brook",
  "Cedar",
  "Dale",
  "Elm",
  "Fern",
  "Glen",
  "Hazel",
  "Ivy",
  "Juniper",
  "Kestrel",
  "Linden",
  "Moss",
  "Oak",
  "Pine",
  "Quarry",
  "Rowan",
  "Sorrel",
  "Thorn",
  "Willow",
];
const SECOND = [
  "Lane",
  "Court",
  "Green",
  "Row",
  "Bank",
  "Cross",
  "Hill",
  "Mead",
  "Wharf",
  "Yard",
];

function makeAccounts(count: number): Account[] {
  const random = seededRandom(97);
  const pick = <T>(list: T[]) => list[Math.floor(random() * list.length)]!;
  return Array.from({ length: count }, (_, id) => {
    const planRoll = random();
    const plan = planRoll < 0.55 ? "Solo" : planRoll < 0.88 ? "Team" : "Group";
    const base = plan === "Solo" ? 49 : plan === "Team" ? 180 : 620;
    const healthRoll = random();
    const health: Health =
      healthRoll < 0.52
        ? "healthy"
        : healthRoll < 0.8
          ? "steady"
          : healthRoll < 0.94
            ? "risk"
            : "leaving";
    const industry = pick(INDUSTRIES);
    return {
      id,
      name: `${pick(FIRST)} ${pick(SECOND)} ${industry.ending}`,
      plan,
      region: pick(REGIONS),
      industry: industry.name,
      health,
      revenue: Math.round(base * (0.6 + random() * random() * 3.2)),
    };
  });
}

/** Every account, invented for the sample. */
export const ACCOUNTS = makeAccounts(1800);

/** The five groupings, in tab order. */
export const GROUPINGS: Grouping[] = [
  {
    id: "all",
    label: "All",
    groups: ["All accounts"],
    of: () => "All accounts",
  },
  { id: "plan", label: "Plan", groups: PLANS, of: (account) => account.plan },
  {
    id: "region",
    label: "Region",
    groups: REGIONS,
    of: (account) => account.region,
  },
  {
    id: "health",
    label: "Health",
    groups: HEALTH_ORDER.map((health) => HEALTH[health].label),
    of: (account) => HEALTH[account.health].label,
  },
  {
    id: "industry",
    label: "Industry",
    groups: INDUSTRIES.map((industry) => industry.name),
    of: (account) => account.industry,
  },
];

/** The dot radius of an account, in world units: area grows with revenue. */
export const dotRadius = (revenue: number) => 0.8 + Math.sqrt(revenue) * 0.16;

/** One cluster of accounts and where it sits. */
export interface Cluster {
  name: string;
  x: number;
  y: number;
  radius: number;
  /** Account ids, largest revenue first. */
  members: number[];
  revenue: number;
}

/**
 * Lays out the clusters of a grouping on a ring, and each cluster's accounts
 * as a sunflower spiral with the largest accounts at its heart. Returns the
 * clusters and every account's resting place.
 */
export function layoutGalaxy(grouping: Grouping) {
  const targets = ACCOUNTS.map(() => ({ x: 0, y: 0 }));
  const count = grouping.groups.length;
  const ring = count === 1 ? 0 : 150 + count * 12;
  const golden = Math.PI * (3 - Math.sqrt(5));
  const clusters: Cluster[] = grouping.groups.map((name, index) => {
    const members = ACCOUNTS.filter((account) => grouping.of(account) === name)
      .sort((a, b) => b.revenue - a.revenue)
      .map((account) => account.id);
    const angle = (index / count) * Math.PI * 2 - Math.PI / 2;
    const x = Math.cos(angle) * ring * 1.35;
    const y = Math.sin(angle) * ring * 0.8;
    const spacing = count === 1 ? 5.2 : 4.6;
    members.forEach((id, rank) => {
      const distance = spacing * Math.sqrt(rank + 0.5);
      targets[id] = {
        x: x + Math.cos(rank * golden) * distance,
        y: y + Math.sin(rank * golden) * distance,
      };
    });
    const revenue = members.reduce(
      (sum, id) => sum + (ACCOUNTS[id]?.revenue ?? 0),
      0,
    );
    return {
      name,
      x,
      y,
      radius: spacing * Math.sqrt(members.length) + 6,
      members,
      revenue,
    };
  });
  return { clusters, targets };
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import {
  type CSSProperties,
  type KeyboardEvent,
  type MouseEvent,
  type WheelEvent,
  useRef,
  useState,
} from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { MaximizeIcon, PlusIcon } from "../../parts/icons";
import { MinusIcon } from "../icons";
import { PointTip } from "../../parts/point-tip";
import { clamp, springAt, stepSpring } from "../lib/spring";
import { useCanvasSize } from "../lib/use-canvas-size";
import { useFrameLoop } from "../lib/use-frame-loop";
import type { TokenColors } from "../lib/use-token-colors";
import {
  ACCOUNTS,
  type Cluster,
  dotRadius,
  HEALTH,
  HEALTH_ORDER,
} from "./data";

/** Props for the drawn cloud of accounts. */
export interface GalaxyCanvasProps {
  clusters: Cluster[];
  targets: { x: number; y: number }[];
  /** The cluster the camera is on, or null for the whole cloud. */
  focus: number | null;
  onFocus: (cluster: number | null) => void;
  selected: number | null;
  onSelect: (account: number | null) => void;
  colors: TokenColors;
  reduceMotion: boolean;
  active: boolean;
  label: string;
}

const RADII = ACCOUNTS.map((account) => dotRadius(account.revenue));
const PHASE = ACCOUNTS.map((account) => (account.id * 2.399) % (Math.PI * 2));

/**
 * The accounts as dots on a canvas, sized by revenue and coloured by health.
 * When the grouping changes, each dot springs to its new cluster on a curve,
 * so the cloud spirals into place. Left and right fly between clusters, up
 * and down step through the largest accounts of the cluster in view, plus
 * and minus zoom, and Escape clears the account, then the view.
 */
export function GalaxyCanvas(props: GalaxyCanvasProps) {
  const {
    clusters,
    targets,
    focus,
    onFocus,
    selected,
    onSelect,
    colors,
    reduceMotion,
    active,
    label,
  } = props;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const size = useCanvasSize(canvasRef);
  const dots = useRef(
    targets.map((target) => ({
      x: target.x * 0.2,
      y: target.y * 0.2,
      vx: 0,
      vy: 0,
    })),
  );
  const camera = useRef({ x: springAt(0), y: springAt(0), zoom: springAt(1) });
  // Zoom belongs to the cluster in view: flying to another cluster starts it at 1 again.
  const [zoomState, setZoomState] = useState<{
    focus: number | null;
    zoom: number;
  }>({ focus: null, zoom: 1 });
  const zoomGoal = zoomState.focus === focus ? zoomState.zoom : 1;
  const zoomBy = (factor: number) =>
    setZoomState({ focus, zoom: clamp(zoomGoal * factor, 0.5, 6) });
  const [view, setView] = useState({ x: 0, y: 0, scale: 1 });
  const [hovered, setHovered] = useState<number | null>(null);
  const time = useRef(0);
  const shown = hovered ?? selected;

  // The extent of the whole cloud, so "fit" frames every cluster.
  // The top margin leaves room for the cluster labels above the highest cluster.
  const extentX = Math.max(
    ...clusters.map((cluster) => Math.abs(cluster.x) + cluster.radius),
  );
  const extentY = Math.max(
    ...clusters.map((cluster) => Math.abs(cluster.y) + cluster.radius),
  );
  const fitScale =
    Math.min(size.width / 2 / extentX, (size.height / 2 - 24) / extentY) *
      0.94 || 1;
  const focusCluster = focus === null ? null : clusters[focus];
  const goal = focusCluster
    ? {
        x: focusCluster.x,
        y: focusCluster.y,
        scale:
          (Math.min(size.width, size.height) / 2 / focusCluster.radius) *
          0.85 *
          zoomGoal,
      }
    : { x: 0, y: 0, scale: fitScale * zoomGoal };

  const step = (seconds: number) => {
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context || size.width === 0) return false;
    time.current += seconds;
    let moving = !reduceMotion;
    const cam = camera.current;
    for (const [key, value] of [
      ["x", goal.x],
      ["y", goal.y],
      ["zoom", goal.scale],
    ] as const) {
      if (reduceMotion) cam[key].value = value;
      else if (stepSpring(cam[key], value, seconds, 70, 17)) moving = true;
    }
    const list = dots.current;
    for (let index = 0; index < list.length; index++) {
      const dot = list[index]!;
      const target = targets[index]!;
      if (reduceMotion) {
        dot.x = target.x;
        dot.y = target.y;
        continue;
      }
      const dx = target.x - dot.x;
      const dy = target.y - dot.y;
      // A sideways pull turns a straight move into a spiral. It fades as the dot arrives.
      const swirl = Math.min(1, Math.hypot(dx, dy) / 200) * 1.6;
      const ax = dx * 9 - dy * swirl * 4 - dot.vx * 5.5;
      const ay = dy * 9 + dx * swirl * 4 - dot.vy * 5.5;
      dot.vx += ax * seconds;
      dot.vy += ay * seconds;
      dot.x += dot.vx * seconds;
      dot.y += dot.vy * seconds;
    }

    const { width, height, ratio } = size;
    const scale = cam.zoom.value;
    const ox = width / 2 - cam.x.value * scale;
    const oy = height / 2 - cam.y.value * scale;
    context.setTransform(ratio, 0, 0, ratio, 0, 0);
    context.clearRect(0, 0, width, height);
    const drift = reduceMotion ? 0 : 1.4;
    const dimmed = focus === null ? null : new Set(clusters[focus]?.members);
    for (const health of HEALTH_ORDER) {
      context.fillStyle = colors.chart[HEALTH[health].hue];
      for (const pass of [0, 1]) {
        context.globalAlpha = pass === 0 ? 0.28 : 0.88;
        context.beginPath();
        for (let index = 0; index < list.length; index++) {
          const account = ACCOUNTS[index]!;
          if (account.health !== health) continue;
          const inFocus = dimmed === null || dimmed.has(index);
          if (inFocus !== (pass === 1)) continue;
          const dot = list[index]!;
          const phase = PHASE[index]!;
          const x =
            ox + (dot.x + Math.sin(time.current * 0.6 + phase) * drift) * scale;
          const y =
            oy + (dot.y + Math.cos(time.current * 0.5 + phase) * drift) * scale;
          const radius = Math.max(0.8, RADII[index]! * scale);
          if (
            x < -radius ||
            x > width + radius ||
            y < -radius ||
            y > height + radius
          )
            continue;
          context.moveTo(x + radius, y);
          context.arc(x, y, radius, 0, Math.PI * 2);
        }
        context.fill();
      }
    }
    if (shown !== null) {
      const dot = list[shown]!;
      context.globalAlpha = 1;
      context.strokeStyle = colors.foreground;
      context.lineWidth = 2;
      context.beginPath();
      context.arc(
        ox + dot.x * scale,
        oy + dot.y * scale,
        RADII[shown]! * scale + 3,
        0,
        Math.PI * 2,
      );
      context.stroke();
    }
    setView((current) =>
      Math.abs(current.x - cam.x.value) +
        Math.abs(current.y - cam.y.value) +
        Math.abs(current.scale - scale) >
      0.01
        ? { x: cam.x.value, y: cam.y.value, scale }
        : current,
    );
    return moving;
  };

  useFrameLoop(
    step,
    active,
    `${size.width}-${colors.foreground}-${reduceMotion}-${focus}-${zoomGoal}-${shown}-${targets.length}-${clusters.length}-${clusters[0]?.name}`,
  );

  const toScreen = (x: number, y: number) => ({
    x: size.width / 2 + (x - view.x) * view.scale,
    y: size.height / 2 + (y - view.y) * view.scale,
  });

  const accountAt = (event: MouseEvent<HTMLCanvasElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    const px = event.clientX - box.left;
    const py = event.clientY - box.top;
    let best: number | null = null;
    let bestDistance = 12;
    dots.current.forEach((dot, index) => {
      const point = toScreen(dot.x, dot.y);
      const distance =
        Math.hypot(point.x - px, point.y - py) - RADII[index]! * view.scale;
      if (distance < bestDistance) {
        best = index;
        bestDistance = distance;
      }
    });
    return best;
  };

  const members =
    focus === null ? [] : (clusters[focus]?.members.slice(0, 40) ?? []);
  const onKeyDown = (event: KeyboardEvent<HTMLCanvasElement>) => {
    const count = clusters.length;
    if (event.key === "ArrowRight")
      onFocus(focus === null ? 0 : (focus + 1) % count);
    else if (event.key === "ArrowLeft")
      onFocus(focus === null ? count - 1 : (focus - 1 + count) % count);
    else if (
      (event.key === "ArrowDown" || event.key === "ArrowUp") &&
      members.length > 0
    ) {
      const at = selected === null ? -1 : members.indexOf(selected);
      const next =
        event.key === "ArrowDown"
          ? Math.min(members.length - 1, at + 1)
          : Math.max(0, at - 1);
      onSelect(members[next] ?? null);
    } else if (event.key === "ArrowDown" || event.key === "ArrowUp") onFocus(0);
    else if (event.key === "+" || event.key === "=") zoomBy(1.3);
    else if (event.key === "-" || event.key === "_") zoomBy(1 / 1.3);
    else if (event.key === "Escape") {
      if (selected !== null) onSelect(null);
      else if (focus !== null || zoomGoal !== 1) {
        onFocus(null);
        setZoomState({ focus: null, zoom: 1 });
      } else return;
    } else return;
    event.preventDefault();
  };

  const onWheel = (event: WheelEvent<HTMLCanvasElement>) => {
    if (event.ctrlKey) zoomBy(Math.exp(-event.deltaY * 0.01));
  };

  const account = shown === null ? null : ACCOUNTS[shown];
  const tipAt =
    shown === null
      ? null
      : toScreen(targets[shown]?.x ?? 0, targets[shown]?.y ?? 0);

  return (
    <div className="relative h-80 w-full @2xl:h-96">
      <canvas
        ref={canvasRef}
        role="application"
        aria-roledescription="account map"
        aria-label={label}
        tabIndex={0}
        className="size-full cursor-pointer touch-pan-y rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring"
        onKeyDown={onKeyDown}
        onWheel={onWheel}
        onPointerMove={(event) =>
          event.pointerType === "mouse" && setHovered(accountAt(event))
        }
        onPointerLeave={() => setHovered(null)}
        onClick={(event) => {
          const hit = accountAt(event);
          if (hit !== null) {
            onSelect(hit);
            return;
          }
          // A click on empty space inside a cluster flies to it.
          const box = event.currentTarget.getBoundingClientRect();
          const index = clusters.findIndex((cluster) => {
            const point = toScreen(cluster.x, cluster.y);
            return (
              Math.hypot(
                point.x - (event.clientX - box.left),
                point.y - (event.clientY - box.top),
              ) <
              cluster.radius * view.scale
            );
          });
          if (index >= 0 && clusters.length > 1) onFocus(index);
          else onSelect(null);
        }}
      />
      {clusters.length > 1
        ? clusters.map((cluster, index) => {
            const point = toScreen(cluster.x, cluster.y - cluster.radius);
            if (
              point.x < 0 ||
              point.x > size.width ||
              point.y < 0 ||
              point.y > size.height
            )
              return null;
            return (
              <span
                key={cluster.name}
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute top-(--y) left-(--x) -mt-1 -translate-x-1/2 -translate-y-full rounded-full bg-popover px-2 py-0.5 text-xs font-medium whitespace-nowrap text-popover-foreground shadow-sm",
                  focus !== null && focus !== index && "opacity-50",
                )}
                // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                style={
                  {
                    "--x": `${(point.x / size.width) * 100}%`,
                    "--y": `${(point.y / size.height) * 100}%`,
                  } as CSSProperties
                }
              >
                {cluster.name} {cluster.members.length}
              </span>
            );
          })
        : null}
      <div className="absolute right-2 bottom-2 flex gap-1">
        <Button
          variant="outline"
          size="icon"
          aria-label="Zoom out"
          onClick={() => zoomBy(1 / 1.3)}
        >
          <MinusIcon className="size-4" />
        </Button>
        <Button
          variant="outline"
          size="icon"
          aria-label="Zoom in"
          onClick={() => zoomBy(1.3)}
        >
          <PlusIcon aria-hidden="true" className="size-4" />
        </Button>
        <Button
          variant="outline"
          size="icon"
          aria-label="Show every account"
          onClick={() => {
            onSelect(null);
            onFocus(null);
            setZoomState({ focus: null, zoom: 1 });
          }}
        >
          <MaximizeIcon aria-hidden="true" className="size-4" />
        </Button>
      </div>
      {account && tipAt ? (
        <PointTip
          x={(tipAt.x / (size.width || 1)) * 100}
          y={(tipAt.y / (size.height || 1)) * 100}
          title={account.name}
          rows={[
            {
              label: "Monthly revenue",
              value: formatMoney(account.revenue),
              marker: HEALTH[account.health].fill,
            },
            { label: "Health", value: HEALTH[account.health].label },
            { label: "Plan", value: account.plan },
          ]}
          note={`${account.region}, ${account.industry.toLowerCase()}`}
        />
      ) : null}
    </div>
  );
}

