export interface GalaxyPanelProps {
  clusters: Cluster[];
  focus: number | null;
  onFocus: (cluster: number | null) => void;
}

type Measure = "revenue" | "accounts";

const BARS = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
];
const TOTAL_REVENUE = ACCOUNTS.reduce(
  (sum, account) => sum + account.revenue,
  0,
);

/**
 * Total revenue and accounts, and one row per cluster that a person can
 * rank by revenue or by accounts. Rows slide to their new order, and a row
 * flies the map to its cluster. With one cluster it breaks down by health.
 */
export function GalaxyPanel({ clusters, focus, onFocus }: GalaxyPanelProps) {
  const [measure, setMeasure] = useState<Measure>("revenue");
  const reduceMotion = useReducedMotion();
  const single = clusters.length === 1;
  const rows = single
    ? HEALTH_ORDER.map((health) => {
        const members = ACCOUNTS.filter((account) => account.health === health);
        return {
          name: HEALTH[health].label,
          index: -1,
          bar: HEALTH[health].fill,
          accounts: members.length,
          revenue: members.reduce((sum, account) => sum + account.revenue, 0),
        };
      })
    : clusters.map((cluster, index) => ({
        name: cluster.name,
        index,
        bar: BARS[index % BARS.length]!,
        accounts: cluster.members.length,
        revenue: cluster.revenue,
      }));
  const value = (row: (typeof rows)[number]) =>
    measure === "revenue" ? row.revenue : row.accounts;
  const sorted = [...rows].sort((a, b) => value(b) - value(a));
  const top = Math.max(1, ...rows.map(value));

  return (
    <div className="flex flex-col gap-4">
      <dl className="grid grid-cols-2 gap-3">
        <div className="flex flex-col gap-0.5">
          <dt className="text-sm text-muted-foreground">Monthly revenue</dt>
          <dd>
            <RollingText
              text={formatMoney(TOTAL_REVENUE)}
              className="text-2xl font-semibold tracking-tight"
            />
          </dd>
        </div>
        <div className="flex flex-col gap-0.5">
          <dt className="text-sm text-muted-foreground">Accounts</dt>
          <dd>
            <RollingText
              text={formatWhole(ACCOUNTS.length)}
              className="text-2xl font-semibold tracking-tight"
            />
          </dd>
        </div>
      </dl>
      <SegmentedControl
        aria-label="Rank by"
        options={[
          { value: "revenue", label: "Revenue" },
          { value: "accounts", label: "Accounts" },
        ]}
        value={measure}
        onValueChange={setMeasure}
      />
      <ol
        aria-label={single ? "Accounts by health" : "Clusters"}
        className="flex flex-col gap-0.5"
      >
        {sorted.map((row) => {
          const active = row.index >= 0 && row.index === focus;
          const label =
            measure === "revenue"
              ? formatMoney(row.revenue)
              : formatWhole(row.accounts);
          const content = (
            <>
              <span className="flex w-full items-center justify-between gap-3">
                <span>{row.name}</span>
                <span className="font-medium tabular-nums">{label}</span>
              </span>
              <span
                aria-hidden="true"
                className="h-1 w-full rounded-full bg-muted"
              >
                <span
                  className={cn("block h-full w-(--bar) rounded-full", row.bar)}
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={
                    { "--bar": `${(value(row) / top) * 100}%` } as CSSProperties
                  }
                />
              </span>
            </>
          );
          return (
            <motion.li
              key={row.name}
              layout={!reduceMotion}
              transition={{ type: "spring", stiffness: 420, damping: 38 }}
            >
              {single ? (
                <div className="flex flex-col gap-1 px-2.5 py-1.5 text-sm">
                  {content}
                </div>
              ) : (
                <Button
                  variant="ghost"
                  size="sm"
                  aria-pressed={active}
                  onClick={() => onFocus(active ? null : row.index)}
                  className="relative isolate w-full text-left"
                >
                  {active ? (
                    <span
                      aria-hidden="true"
                      className="absolute inset-0 -z-10 rounded-lg bg-muted"
                    />
                  ) : null}
                  <span
                    className={cn(
                      "flex w-full flex-col gap-1 px-2.5 py-1.5 font-normal",
                      focus !== null && !active && "opacity-60",
                    )}
                  >
                    {content}
                  </span>
                </Button>
              )}
            </motion.li>
          );
        })}
      </ol>
    </div>
  );
}

"use client";

import { type RefObject, useEffect, useState } from "react";

/**
 * Says whether the element is on screen, so a showpiece can stop drawing
 * frames while it is scrolled away. It reads false until the first check.
 */
export function useInView(ref: RefObject<Element | null>): boolean {
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry?.isIntersecting ?? false),
      { rootMargin: "64px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref]);
  return inView;
}
